import React, { useState, useEffect } from 'react';
import { Page, ContentItem } from './types';
import { ICONS, INITIAL_PROJECTS, APP_VERSION } from './constants';
import Sidebar from './components/Sidebar';
import Home from './pages/Home';
import Projects from './pages/Projects';
import Tools from './pages/Tools';
import More from './pages/More';
import AdminDashboard from './pages/AdminDashboard';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('nova_is_admin') === 'true');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginPwd, setLoginPwd] = useState('');
  const [loginError, setLoginError] = useState('');

  const [projects, setProjects] = useState<ContentItem[]>(() => {
    const savedVersion = localStorage.getItem('nova_app_version');
    const savedProjects = localStorage.getItem('nova_projects');

    // 如果版本不一致或没有存储数据，则强制使用代码中的 INITIAL_PROJECTS
    if (savedVersion !== APP_VERSION || !savedProjects) {
      console.log(`检测到新版本 ${APP_VERSION}，正在同步远程内容...`);
      localStorage.setItem('nova_app_version', APP_VERSION);
      localStorage.setItem('nova_projects', JSON.stringify(INITIAL_PROJECTS));
      return INITIAL_PROJECTS;
    }

    try {
      return JSON.parse(savedProjects);
    } catch (e) {
      return INITIAL_PROJECTS;
    }
  });

  useEffect(() => {
    localStorage.setItem('nova_projects', JSON.stringify(projects));
  }, [projects]);

  useEffect(() => {
    const handleResize = () => {
      const isMobile = window.innerWidth < 768;
      setIsSidebarOpen(!isMobile);
      if (isMobile) setIsSidebarCollapsed(false);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const encoded = btoa(unescape(encodeURIComponent(loginPwd)));
    if (encoded === 'Y2hlbjEyMzQ=') {
      setIsAdmin(true);
      localStorage.setItem('nova_is_admin', 'true');
      setShowLoginModal(false);
      setLoginPwd('');
      setLoginError('');
    } else {
      setLoginError('身份校验失败，请检查管理通行证');
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('nova_is_admin');
    if (currentPage === Page.ADMIN) setCurrentPage(Page.HOME);
  };

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME: return <Home projects={projects} onNavigate={setCurrentPage} />;
      case Page.ARTICLES: return (
        <Projects 
          title="深度文章"
          description="沉淀技术思考，分享实战心得。"
          projects={projects.filter(p => p.type === 'article')} 
        />
      );
      case Page.PROJECTS: return (
        <Projects 
          title="实战项目"
          description="涵盖从交通仿真到企业级前端的研究。"
          projects={projects.filter(p => p.type === 'project')} 
        />
      );
      case Page.TOOLS: return <Tools />;
      case Page.MORE: return <More />;
      case Page.ADMIN: return isAdmin ? (
        <AdminDashboard 
          projects={projects} 
          setProjects={setProjects} 
          onLogout={handleLogout}
        />
      ) : <Home projects={projects} onNavigate={setCurrentPage} />;
      default: return <Home projects={projects} onNavigate={setCurrentPage} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900 transition-all duration-300">
      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-white border-b border-slate-200 z-40 flex items-center px-4 justify-between glass-effect">
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">陈</div>
          <span className="font-bold text-xl tracking-tight">陈凌</span>
        </div>
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-100 rounded-lg">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
          </svg>
        </button>
      </div>

      <Sidebar 
        activePage={currentPage} 
        onPageChange={setCurrentPage} 
        isOpen={isSidebarOpen}
        isCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
        isAdmin={isAdmin}
        onOpenLogin={() => setShowLoginModal(true)}
      />

      <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? (isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64') : 'md:ml-0'} pt-16 md:pt-0`}>
        <div className="max-w-6xl mx-auto p-4 md:p-8">
          {renderPage()}
        </div>
      </main>

      {/* Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setShowLoginModal(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[32px] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h2 className="text-2xl font-bold text-center mb-6">身份验证</h2>
            <form onSubmit={handleLogin} className="space-y-4">
              <input 
                autoFocus
                type="password" 
                placeholder="请输入管理通行证" 
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 text-center"
                value={loginPwd}
                onChange={e => setLoginPwd(e.target.value)}
              />
              {loginError && <p className="text-red-500 text-xs text-center">{loginError}</p>}
              <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition-all shadow-lg">
                解锁管理功能
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ContentItem } from '../types';
import { ICONS, INITIAL_PROJECTS, APP_VERSION } from '../constants';

interface AdminDashboardProps {
  projects: ContentItem[];
  setProjects: (projects: ContentItem[]) => void;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, onLogout }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<ContentItem>>({});
  const [showSyncSuccess, setShowSyncSuccess] = useState(false);

  const toggleFeatured = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, isFeatured: !p.isFeatured } : p));
  };

  const toggleLatest = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, isLatest: !p.isLatest } : p));
  };

  const startEdit = (p: ContentItem) => {
    setEditingId(p.id);
    setEditForm(p);
  };

  const saveEdit = () => {
    if (!editingId) return;
    setProjects(projects.map(p => p.id === editingId ? { ...p, ...editForm } : p));
    setEditingId(null);
  };

  const handleSyncWithCode = () => {
    if (window.confirm('此操作将用 GitHub 源码中的初始配置覆盖您在本地的所有修改，确定吗？')) {
      setProjects(INITIAL_PROJECTS);
      localStorage.setItem('nova_app_version', APP_VERSION);
      setShowSyncSuccess(true);
      setTimeout(() => setShowSyncSuccess(false), 3000);
    }
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold">管理员控制台</h1>
          <p className="text-slate-500 flex items-center mt-1">
            当前核心数据版本: <span className="ml-2 px-2 py-0.5 bg-slate-200 text-slate-700 rounded text-xs font-mono">{APP_VERSION}</span>
          </p>
        </div>
        <div className="flex items-center space-x-3">
          <button 
            onClick={handleSyncWithCode}
            className="flex items-center space-x-2 px-6 py-2 bg-indigo-50 text-indigo-600 rounded-xl font-bold hover:bg-indigo-100 transition-all text-sm border border-indigo-100"
          >
            <ICONS.Refresh className={`w-4 h-4 ${showSyncSuccess ? 'animate-spin' : ''}`} />
            <span>{showSyncSuccess ? '已同步' : '同步 GitHub 数据'}</span>
          </button>
          <button onClick={onLogout} className="px-6 py-2 border border-red-200 text-red-600 rounded-xl font-bold hover:bg-red-50 transition-all text-sm">
            退出登录
          </button>
        </div>
      </div>

      {/* Projects Management */}
      <section className="bg-white rounded-[32px] border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-center">
          <h2 className="font-bold text-lg">内容资源管理</h2>
          <span className="text-[10px] text-slate-400 bg-white px-3 py-1 rounded-full border border-slate-100">共 {projects.length} 项资产</span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-slate-400 text-[10px] font-bold uppercase tracking-widest border-b border-slate-50">
                <th className="px-6 py-4">内容名称</th>
                <th className="px-6 py-4">类型</th>
                <th className="px-6 py-4">展示权重</th>
                <th className="px-6 py-4">链接 / 配置</th>
                <th className="px-6 py-4">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {projects.map(p => (
                <tr key={p.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <img src={p.image} className="w-10 h-10 rounded-lg object-cover" alt="" />
                      <div className="min-w-0">
                        <p className="font-bold text-sm truncate">{p.name}</p>
                        <p className="text-[10px] text-slate-400 truncate max-w-[150px]">{p.description}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${p.type === 'article' ? 'bg-amber-100 text-amber-700' : 'bg-blue-100 text-blue-700'}`}>
                      {p.type === 'article' ? '文章' : '项目'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col space-y-1">
                      <button 
                        onClick={() => toggleFeatured(p.id)}
                        className={`px-3 py-1 rounded-lg text-[10px] font-bold transition-all text-left ${p.isFeatured ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400'}`}
                      >
                        {p.isFeatured ? '★ 精选' : '设为精选'}
                      </button>
                      <button 
                        onClick={() => toggleLatest(p.id)}
                        className={`px-3 py-1 rounded-lg text-[10px] font-bold transition-all text-left ${p.isLatest ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-400'}`}
                      >
                        {p.isLatest ? '● 最新' : '标记最新'}
                      </button>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-[10px] font-mono text-slate-400 space-y-1">
                      <p className="truncate max-w-[180px]">Link: {p.link}</p>
                      <p>File: {p.articleId}.md</p>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <button 
                      onClick={() => startEdit(p)}
                      className="p-2 text-slate-400 hover:text-indigo-600 transition-colors hover:bg-white rounded-lg shadow-sm"
                    >
                      <ICONS.Edit className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Quick Edit Form (Modal Style) */}
      {editingId && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setEditingId(null)} />
          <div className="relative bg-white w-full max-w-lg rounded-[32px] p-8 shadow-2xl animate-in zoom-in-95">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold">修改内容信息</h2>
              <button onClick={() => setEditingId(null)} className="text-slate-400 hover:text-slate-600">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth={2}/></svg>
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">标题</label>
                <input 
                  type="text" 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                  value={editForm.name || ''}
                  onChange={e => setEditForm({...editForm, name: e.target.value})}
                />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">描述</label>
                <textarea 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px]"
                  value={editForm.description || ''}
                  onChange={e => setEditForm({...editForm, description: e.target.value})}
                />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1 block">外部链接 (URL)</label>
                <input 
                  type="text" 
                  className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500"
                  value={editForm.link || ''}
                  onChange={e => setEditForm({...editForm, link: e.target.value})}
                />
              </div>
              <div className="flex gap-3 pt-4">
                <button 
                  onClick={saveEdit}
                  className="flex-1 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg"
                >
                  保存本地修改
                </button>
                <button 
                  onClick={() => setEditingId(null)}
                  className="px-6 py-3 border border-slate-200 text-slate-500 rounded-xl font-bold hover:bg-slate-50 transition-all"
                >
                  取消
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="p-10 bg-slate-900 rounded-[40px] text-center text-white">
        <ICONS.Sparkles className="w-8 h-8 text-indigo-400 mx-auto mb-4" />
        <h3 className="font-bold mb-2">同步指南</h3>
        <p className="text-sm text-slate-400 max-w-md mx-auto leading-relaxed">
          如果您在 GitHub 的 <code className="text-indigo-300">constants.tsx</code> 中修改了文章列表，请务必同时更新 <code className="text-indigo-300">APP_VERSION</code>。用户的浏览器检测到版本变化后，将自动清空旧缓存并加载新内容。
        </p>
      </div>
    </div>
  );
};

export default AdminDashboard;
